text:
Where the pets are
Pets are not spread evenly. Hidalgo, Tlaxcala, Oaxaca and Puebla sit near 73% of homes. Mexico City closes the list at 56%.

pets = FileAttachment("../../data/pets-estados.csv").csv({ typed: true })
mx = FileAttachment("../../data/mx-estados.json").json()

// Same state-code map the Labor Market MX pages use. The topojson keys are
// state codes as strings, so both sides of the join are coerced to numbers
// before lookup (see the id-format bug noted in CLAUDE.md section 13).
entidadPorCodigo = ({
  "1": "Aguascalientes", "2": "Baja California", "3": "Baja California Sur",
  "4": "Campeche", "5": "Coahuila", "6": "Colima", "7": "Chiapas",
  "8": "Chihuahua", "9": "Mexico City", "10": "Durango", "11": "Guanajuato",
  "12": "Guerrero", "13": "Hidalgo", "14": "Jalisco", "15": "Mexico State",
  "16": "Michoacán", "17": "Morelos", "18": "Nayarit",
  "19": "Nuevo León", "20": "Oaxaca", "21": "Puebla", "22": "Querétaro",
  "23": "Quintana Roo", "24": "San Luis Potosí", "25": "Sinaloa", "26": "Sonora",
  "27": "Tabasco", "28": "Tamaulipas", "29": "Tlaxcala",
  "30": "Veracruz", "31": "Yucatán", "32": "Zacatecas"
})

// Una rampa por medida, para que al cambiar el selector el mapa se vea
// distinto de inmediato y no solo cambie de tonos. Cada una es de un solo
// tono, claro a oscuro, como pide una escala secuencial: verde azulado para
// el total (el extremo oscuro cae cerca del $teal del sitio), naranja rojizo
// para perro (la familia del $ochre, y lo que ya usan los mapas de Mercado
// Laboral MX) y morado para gato, que es el tercer tono que el sitio ya usa
// en la rampa de edad. Tres tonos bien separados en el circulo cromatico.
medidas = ({
  mascota: { nombre: "Any pet", etiqueta: "Homes with a pet (%)", esquema: "BuGn" },
  perro:   { nombre: "Dog", etiqueta: "Homes with a dog (%)", esquema: "OrRd" },
  gato:    { nombre: "Cat", etiqueta: "Homes with a cat (%)", esquema: "Purples" }
})

mxFeatures = topojson.feature(mx, mx.objects.state).features

graficaMapa = (filas, etiqueta, esquema, { width = 640, height = 430 } = {}) =&gt; {
  const porCodigo = new Map(filas.map(d =&gt; [d.cve_ent, d]));
  const features = mxFeatures.map(f =&gt; {
    const fila = porCodigo.get(+f.properties.id);
    return {
      ...f,
      nombre: entidadPorCodigo[+f.properties.id],
      valor: fila ? fila.valor : undefined,
      ee: fila ? fila.ee : undefined
    };
  });
  return Plot.plot({
    width, height,
    style: { background: "transparent", fontFamily: "IBM Plex Sans, sans-serif", fontSize: "12px", color: "var(--ink)" },
    projection: { type: "mercator", domain: { type: "FeatureCollection", features } },
    color: { type: "linear", scheme: esquema, label: etiqueta, legend: true },
    marks: [
      Plot.geo(features, {
        fill: d =&gt; d.valor,
        stroke: "var(--ink)", strokeWidth: 1,
        tip: true,
        title: d =&gt; `${d.nombre}\n${etiqueta}: ${d.valor.toFixed(1)} ± ${(1.96 * d.ee).toFixed(1)}`
      })
    ]
  });
}












































viewof medida_sel = Inputs.select(Object.keys(medidas), {
  value: "mascota",
  label: "Pet",
  format: d =&gt; medidas[d].nombre
})







filasMapa = pets.map(d =&gt; ({ cve_ent: d.cve_ent, valor: d[medida_sel], ee: d[medida_sel + "_ee"] }))
etiquetaMapa = medidas[medida_sel].etiqueta
esquemaMapa = medidas[medida_sel].esquema
























graficaMapa(filasMapa, etiquetaMapa, esquemaMapa)

ENOE, INEGI · Quarterly, 2005–2026 · National


html`&lt;div class="indicator-meta"&gt;Latest available data: ENOE ${ultimoPeriodoGlobal}&lt;/div&gt;`






Official statistics from Mexico’s National Survey of Occupation and Employment (ENOE), public data from INEGI. Recomputed here from microdata using the institute’s own methodology (survey design, strata, and expansion factors, not a simple average) and checked against the original series INEGI publishes in its Banco de Información Económica. That check runs over every quarter back to 2005, not only the most recent one: the median gap is 0.013 percentage points and the largest is 0.216. Not an original finding: these are public figures, presented here for quick reference.
Start from a question:

Who takes part in the labor market, by sex, age, schooling, and state? Participation.
How many people work without the protections of a formal job? Informality.
How much of the workforce is unemployed, discouraged, or working fewer hours than it wants? Unemployment.
What changed this quarter? Quarterly Update.


raw = FileAttachment("data/labor-indicators.csv").csv({ typed: true })
ajustadaRaw = FileAttachment("data/labor-seasonal.csv").csv({ typed: true })

datos = raw.map(d =&gt; ({ ...d, fecha: new Date(d.anio, (d.trimestre - 1) * 3, 1) }))

// Latest quarter present in the CSV, regardless of indicator -- they all
// share the same latest period since they come from the same export.
ultimoPeriodoGlobal = {
  const ordenado = [...datos].sort((a, b) =&gt; a.fecha - b.fecha);
  const u = ordenado[ordenado.length - 1];
  return `${u.anio}-Q${u.trimestre}`;
}

definiciones = ({
  TPEA: {
    nombre: "Labor force participation",
    texto: "Share of the population 15 and older that is working or actively looking for work."
  },
  TD: {
    nombre: "Unemployment",
    texto: "Share of the labor force that is not working but is actively looking for work."
  },
  TIL1: {
    nombre: "Labor informality",
    texto: "Share of employed people working without the legal and social protections of a formal job (social security, benefits), regardless of whether the business itself is registered."
  },
  TIL2: {
    nombre: "Labor informality, excl. agriculture",
    texto: "Same as labor informality, excluding agriculture — a sector where informality is structurally high and can obscure the trend in the rest of the economy."
  },
  TOSI1: {
    nombre: "Employment in the informal sector",
    texto: "Share of employed people working for a business that operates without registering with the authorities. Measures the type of business, not whether the individual has social security."
  },
  TOSI2: {
    nombre: "Informal-sector employment, excl. agriculture",
    texto: "Same as employment in the informal sector, excluding agriculture."
  },
  TSUB: {
    nombre: "Underemployment",
    texto: "Share of employed people who want, and are able, to work more hours than their current job gives them."
  },
  TCCO: {
    nombre: "Critical employment conditions",
    texto: "Share of employed people in precarious conditions: too few hours involuntarily, or long hours at below the legal minimum wage. Sensitive to minimum-wage changes — treat level shifts with caution, trend direction is more reliable."
  },
  TDAMPL: {
    nombre: "Broader unemployment",
    texto: "The unemployment rate, widened in both numerator and denominator to include people available to work who aren't actively searching (discouraged workers). Not a custom definition: it only combines categories ENOE already reports separately."
  },
  SUBUTIL: {
    nombre: "Labor underutilization",
    texto: "Same as broader unemployment, adding people who already have a job but work fewer hours than they'd like (underemployed). The broadest measure here of how much available labor is going unused."
  }
})

indicadoresPrincipales = ["TPEA", "TIL1", "TD"]
indicadoresEscalera = ["TDAMPL", "SUBUTIL"]
indicadoresSecundarios = Object.keys(definiciones)
  .filter(k =&gt; !indicadoresPrincipales.includes(k) && !indicadoresEscalera.includes(k))
  .sort()

serieDe = codigo =&gt; datos
  .filter(d =&gt; d.indicador === codigo)
  .sort((a, b) =&gt; a.fecha - b.fecha)

valorEnPeriodo = (serie, anio, trimestre) =&gt; {
  const fila = serie.find(d =&gt; d.anio === anio && d.trimestre === trimestre);
  return fila ? fila.valor : null;
}

calcularDeltas = serie =&gt; {
  const ultimo = serie[serie.length - 1];
  const trimAnt = ultimo.trimestre === 1
    ? { anio: ultimo.anio - 1, trimestre: 4 }
    : { anio: ultimo.anio, trimestre: ultimo.trimestre - 1 };
  const valorTrimAnt = valorEnPeriodo(serie, trimAnt.anio, trimAnt.trimestre);
  const valorAnioAnt = valorEnPeriodo(serie, ultimo.anio - 1, ultimo.trimestre);
  return {
    deltaTrim: valorTrimAnt != null ? ultimo.valor - valorTrimAnt : null,
    deltaAnual: valorAnioAnt != null ? ultimo.valor - valorAnioAnt : null
  };
}

// Neutral on purpose: arrows and numbers, no red/green "good or bad" coding.
formatoDelta = delta =&gt; {
  if (delta == null) return "n/a";
  if (Math.abs(delta) &lt; 0.005) return "no change";
  const signo = delta &gt; 0 ? "▲" : "▼";
  return `${signo} ${Math.abs(delta).toFixed(2)} pp`;
}

// nice:true rounds the domain to "nice" numbers, which can pad it well past
// the series' actual range and flatten a series with little variation (e.g.
// TOSI1/TOSI2, which move within ~3 points). Fit the domain to each series'
// own min/max plus a fixed margin instead, so every mini chart uses its own
// scale without exaggerating or flattening.
dominioAjustado = (serie, margenMinimo = 0.4) =&gt; {
  const valores = serie.map(d =&gt; d.valor);
  const min = Math.min(...valores), max = Math.max(...valores);
  const margen = Math.max((max - min) * 0.15, margenMinimo);
  return [min - margen, max + margen];
}

// 2020-Q2 does not exist in the source. ENOE was suspended and replaced by
// the ETOE telephone survey, which INEGI does not publish as a comparable
// estimate. Joining the two sides with a straight line reads a change of
// method as a gradual transition, so a point with an undefined value is
// inserted in the gap and Plot breaks the line there instead.
conHuecos = serie =&gt; {
  const salida = [];
  for (let i = 0; i &lt; serie.length; i++) {
    salida.push(serie[i]);
    if (i &lt; serie.length - 1) {
      const a = serie[i], b = serie[i + 1];
      const meses = (b.fecha.getFullYear() - a.fecha.getFullYear()) * 12 +
                    (b.fecha.getMonth() - a.fecha.getMonth());
      if (meses &gt; 3) {
        salida.push({ ...a,
          fecha: new Date(a.fecha.getFullYear(), a.fecha.getMonth() + 3, 1),
          valor: undefined, ee: undefined });
      }
    }
  }
  return salida;
}

// Trend-cycle series, published by INEGI itself in its Banco de Informacion
// Economica. Quarterly ones come as percentages, unlike the monthly ones,
// which are index numbers, so they sit directly on the same axis as the
// original series with no rescaling. Six indicators have one; the rest return
// an empty array and simply get no background line.
serieAjustada = (codigo, tipo = "tendencia_ciclo") =&gt; ajustadaRaw
  .filter(d =&gt; d.indicador === codigo && d.tipo === tipo)
  .map(d =&gt; ({ ...d, fecha: new Date(d.anio, (d.trimestre - 1) * 3, 1) }))
  .sort((a, b) =&gt; a.fecha - b.fecha)

graficaSerie = (serie, { width = 780, height = 340, marginLeft = 42, color = "var(--teal)", ajustada = null } = {}) =&gt; {
  const ultimo = serie[serie.length - 1];
  const serieRota = conHuecos(serie);
  const ajustadaRota = ajustada && ajustada.length ? conHuecos(ajustada) : null;
  return Plot.plot({
    width, height, marginLeft,
    marginBottom: 30,
    style: { fontFamily: "IBM Plex Sans, sans-serif",
             fontSize: width &lt; 400 ? "11px" : "13px",
             color: "currentColor", background: "transparent" },
    y: { label: "%", grid: true, domain: dominioAjustado(serie), ticks: 4 },
    x: { label: null },
    marks: [
      Plot.areaY(serieRota, {
        x: "fecha",
        y1: d =&gt; d.valor == null ? undefined : d.valor - 1.96 * d.ee,
        y2: d =&gt; d.valor == null ? undefined : d.valor + 1.96 * d.ee,
        fill: color, fillOpacity: 0.12
      }),
      // The trend-cycle line is thinner and faded on purpose. It is reading
      // context for the original series, not a second indicator, and the
      // number quoted on the card always comes from the original.
      ...(ajustadaRota ? [Plot.lineY(ajustadaRota, {
        x: "fecha", y: "valor",
        stroke: color, strokeWidth: 1.4, strokeOpacity: 0.5,
        strokeLinejoin: "round", strokeLinecap: "round"
      })] : []),
      Plot.lineY(serieRota, {
        x: "fecha", y: "valor",
        stroke: color, strokeWidth: 2,
        strokeLinejoin: "round", strokeLinecap: "round"
      }),
      Plot.dot(serie, {
        x: "fecha", y: "valor", r: 3.5,
        fill: color, filter: d =&gt; d === ultimo
      }),
      Plot.ruleY([0], { stroke: "currentColor", strokeOpacity: 0.15 }),
      Plot.tip(serie, Plot.pointerX({
        x: "fecha", y: "valor",
        title: d =&gt; `${d.anio}-Q${d.trimestre} (${d.regimen})\n${d.valor}% ± ${(1.96 * d.ee).toFixed(2)} pp\nn = ${d.n_obs.toLocaleString("en-US")}`
      }))
    ]
  });
}

coloresPrincipales = ({
  TPEA: "var(--teal)",
  TIL1: "var(--clay)",
  TD: "var(--ink-soft)"
})

// A light/deep pair of the same neutral (not --teal or --clay, already used
// by TPEA/TIL1) so both cards read as the same theme -- broader unemployment
// -- without duplicating TD's color or each other's.
coloresEscalera = ({
  TDAMPL: "var(--ink-soft-light)",
  SUBUTIL: "var(--ink-soft-deep)"
})
































































































































html`&lt;div class="indicator-grid"&gt;${indicadoresPrincipales.map(codigo =&gt; {
  const serie = serieDe(codigo);
  const ultimo = serie[serie.length - 1];
  const def = definiciones[codigo];
  const { deltaTrim, deltaAnual } = calcularDeltas(serie);
  const div = document.createElement("div");
  div.className = "indicator-card";
  const head = html`&lt;div class="indicator-name"&gt;${def.nombre}
    &lt;span class="indicator-value"&gt;${ultimo.valor}%&lt;/span&gt;
  &lt;/div&gt;
  &lt;div class="indicator-meta"&gt;± ${(1.96 * ultimo.ee).toFixed(2)} pp · ${ultimo.anio}-Q${ultimo.trimestre}&lt;/div&gt;
  &lt;div class="indicator-delta"&gt;${formatoDelta(deltaTrim)} q/q · ${formatoDelta(deltaAnual)} y/y&lt;/div&gt;
  &lt;div class="indicator-desc"&gt;${def.texto}&lt;/div&gt;`;
  div.append(head, graficaSerie(serie, { width: 250, height: 190, marginLeft: 32, color: coloresPrincipales[codigo], ajustada: serieAjustada(codigo) }));
  return div;
})}&lt;/div&gt;`







The subutilization ladder
Unemployment above is the first step. These two widen the definition, one step at a time: first adding people available to work who aren’t actively searching, then people who already have a job but with fewer hours than they’d like.

html`&lt;div class="indicator-grid indicator-grid-2"&gt;${indicadoresEscalera.map(codigo =&gt; {
  const serie = serieDe(codigo);
  const ultimo = serie[serie.length - 1];
  const def = definiciones[codigo];
  const { deltaTrim, deltaAnual } = calcularDeltas(serie);
  const div = document.createElement("div");
  div.className = "indicator-card";
  const head = html`&lt;div class="indicator-name"&gt;${def.nombre}
    &lt;span class="indicator-value"&gt;${ultimo.valor}%&lt;/span&gt;
  &lt;/div&gt;
  &lt;div class="indicator-meta"&gt;± ${(1.96 * ultimo.ee).toFixed(2)} pp · ${ultimo.anio}-Q${ultimo.trimestre}&lt;/div&gt;
  &lt;div class="indicator-delta"&gt;${formatoDelta(deltaTrim)} q/q · ${formatoDelta(deltaAnual)} y/y&lt;/div&gt;
  &lt;div class="indicator-desc"&gt;${def.texto}&lt;/div&gt;`;
  div.append(head, graficaSerie(serie, { width: 380, height: 190, marginLeft: 32, color: coloresEscalera[codigo], ajustada: serieAjustada(codigo) }));
  return div;
})}&lt;/div&gt;`








Other indicators
Five more series, including the informality and informal-sector rates excluding agriculture.

viewof indicador_sel = Inputs.select(indicadoresSecundarios, {
  value: "TIL2",
  label: "Indicator",
  format: d =&gt; `${d} — ${definiciones[d].nombre}`
})







serieSec = serieDe(indicador_sel)
ultimoSec = serieSec[serieSec.length - 1]
defSec = definiciones[indicador_sel]
deltasSec = calcularDeltas(serieSec)






























html`&lt;div class="indicator-headline"&gt;${defSec.nombre}: ${ultimoSec.valor}%&lt;/div&gt;
&lt;div class="indicator-meta"&gt;± ${(1.96 * ultimoSec.ee).toFixed(2)} pp · ${ultimoSec.anio}-Q${ultimoSec.trimestre} · n = ${ultimoSec.n_obs.toLocaleString("en-US")}&lt;/div&gt;
&lt;div class="indicator-delta"&gt;${formatoDelta(deltasSec.deltaTrim)} vs. prior quarter · ${formatoDelta(deltasSec.deltaAnual)} vs. same quarter last year&lt;/div&gt;
&lt;p class="indicator-desc"&gt;${defSec.texto}&lt;/p&gt;`







graficaSerie(serieSec, { ajustada: serieAjustada(indicador_sel) })







All series above are original, without seasonal adjustment. The faint line behind each one is INEGI’s own trend-cycle series, shown as reading context; it is revised backward as new quarters arrive, so the figure quoted on each card always comes from the original series. Broader unemployment and labor underutilization have no quarterly trend-cycle series published by INEGI and appear without one.



How this is built

1. A validated pipeline, not a one-off script. The full computation — downloading each quarter directly from INEGI, harmonizing field names and weights across the ENOE/ENOE-N/ENOE regime changes since 2005, and applying the survey’s complex design (survey::svydesign, ids = upm, strata = est_d_tri, weights = fac_tri) — lives in a separate private R project, not in this site’s repository. The shaded band on each chart, and the ± figure next to each headline number, is a 95% confidence interval (±1.96 standard errors) from that same design, not a simple margin of error. Every rate above is checked against the original series INEGI publishes in its Banco de Información Económica, over the full history rather than only the latest quarter: the median gap is 0.013 percentage points and the largest is 0.216. Broader unemployment and labor underutilization have no matching series there and are reported as unvalidated on the quarterly update page.
2. This site only reads a public CSV. scripts/02-labor-indicators.R exports the national-level rates from that pipeline into data/labor-indicators.csv — nothing else. Re-run it with Rscript scripts/02-labor-indicators.R after the source pipeline updates, which happens once per quarter as INEGI publishes new microdata. All the code on this page — that script and the {ojs} that builds the charts — lives in the site’s repository.
3. The chart reads the CSV client-side. Plain FileAttachment(...).csv() and Observable Plot — no database engine, so nothing depends on a CDN beyond what Quarto already loads for Observable itself.

ENOE, INEGI · Quarterly, 2005–2026 · National

Updated every time INEGI publishes a new quarter: what changed from the prior quarter and from a year earlier, and how closely this pipeline matches the series INEGI itself publishes for that same period. Same quality check described on the overview page, laid out here in full instead of a single summary line.

raw = FileAttachment("data/labor-indicators.csv").csv({ typed: true })
rawCortes = FileAttachment("data/labor-indicators-cuts.csv").csv({ typed: true })
validaciones = FileAttachment("data/validations.csv").csv({ typed: true })

datos = raw.map(d =&gt; ({ ...d, fecha: new Date(d.anio, (d.trimestre - 1) * 3, 1) }))
datosCortes = rawCortes.map(d =&gt; ({ ...d, fecha: new Date(d.anio, (d.trimestre - 1) * 3, 1) }))

nombres = ({
  TPEA: "Labor force participation",
  TD: "Unemployment",
  TIL1: "Labor informality",
  TIL2: "Labor informality (excl. agriculture)",
  TOSI1: "Employment in the informal sector",
  TOSI2: "Informal-sector employment (excl. agriculture)",
  TSUB: "Underemployment",
  TCCO: "Critical employment conditions",
  TDAMPL: "Broader unemployment",
  SUBUTIL: "Labor underutilization"
})

// Notes are keys the page translates, not prose written into this file. The
// validation itself decides which key each row gets (see
// scripts/04-labor-validations.R), so a note can never outlive the condition
// it describes -- which is what happened to the hand-written one it replaced.
notas = ({
  sin_bie: "No matching quarterly series in INEGI's BIE; not validated.",
  excede: "Exceeds the 0.25 pp tolerance against the BIE series."
})

// Only these have sex/age/education/state breakdowns computed so far (see
// Participation/Informality/Unemployment) -- TSUB and TCCO stay national-only.
indicadoresConCortes = ["TPEA", "TIL1", "TIL2", "TOSI1", "TOSI2", "TD", "TDAMPL", "SUBUTIL"]

cortes = ({
  sexo: "Sex", edad: "Age", nivel_educativo: "Education", entidad: "State"
})

// categoria_origen labels in the CSV are Spanish -- map to English for
// display, same lookup used on the three theme pages.
etiquetaEn = ({
  "Hombre": "Men", "Mujer": "Women",
  "15 a 19": "15 to 19", "20 a 29": "20 to 29", "30 a 39": "30 to 39",
  "40 a 49": "40 to 49", "50 a 59": "50 to 59", "60 y más": "60 and over",
  "Primaria incompleta": "Incomplete primary", "Primaria completa": "Primary",
  "Secundaria completa": "Secondary", "Medio superior y superior": "High school and beyond",
  "Ciudad de México": "Mexico City", "Coahuila de Zaragoza": "Coahuila",
  "México": "Mexico State", "Michoacán de Ocampo": "Michoacán",
  "Veracruz de Ignacio de la Llave": "Veracruz"
})

serieDe = codigo =&gt; datos
  .filter(d =&gt; d.indicador === codigo)
  .sort((a, b) =&gt; a.fecha - b.fecha)

valorEnPeriodo = (serie, anio, trimestre) =&gt; {
  const fila = serie.find(d =&gt; d.anio === anio && d.trimestre === trimestre);
  return fila ? fila.valor : null;
}

calcularDeltas = serie =&gt; {
  const ultimo = serie[serie.length - 1];
  const trimAnt = ultimo.trimestre === 1
    ? { anio: ultimo.anio - 1, trimestre: 4 }
    : { anio: ultimo.anio, trimestre: ultimo.trimestre - 1 };
  const valorTrimAnt = valorEnPeriodo(serie, trimAnt.anio, trimAnt.trimestre);
  const valorAnioAnt = valorEnPeriodo(serie, ultimo.anio - 1, ultimo.trimestre);
  return {
    deltaTrim: valorTrimAnt != null ? ultimo.valor - valorTrimAnt : null,
    deltaAnual: valorAnioAnt != null ? ultimo.valor - valorAnioAnt : null,
    baseTrim: valorTrimAnt, baseAnual: valorAnioAnt
  };
}

// Same as valorEnPeriodo/calcularDeltas above, but also carries the
// standard error of each period's estimate through, so the by-group
// section below can tell a real move from sampling noise.
valorEnPeriodoConSE = (serie, anio, trimestre) =&gt; {
  const fila = serie.find(d =&gt; d.anio === anio && d.trimestre === trimestre);
  return fila ? { valor: fila.valor, ee: fila.ee } : null;
}

// SE of a difference between two survey estimates: combine in quadrature,
// assuming independence. ENOE's rotating panel means neighboring quarters
// actually share some of the same respondents, so this slightly overstates
// the true SE of the quarter-over-quarter difference (positive correlation
// between overlapping observations would shrink it) -- the filter below
// errs toward under-claiming significance, not over-claiming it.
calcularDeltasConSE = serie =&gt; {
  const ultimo = serie[serie.length - 1];
  const trimAnt = ultimo.trimestre === 1
    ? { anio: ultimo.anio - 1, trimestre: 4 }
    : { anio: ultimo.anio, trimestre: ultimo.trimestre - 1 };
  const trimAntDato = valorEnPeriodoConSE(serie, trimAnt.anio, trimAnt.trimestre);
  const anioAntDato = valorEnPeriodoConSE(serie, ultimo.anio - 1, ultimo.trimestre);
  return {
    deltaTrim: trimAntDato ? ultimo.valor - trimAntDato.valor : null,
    deltaAnual: anioAntDato ? ultimo.valor - anioAntDato.valor : null,
    seTrim: trimAntDato ? Math.sqrt(ultimo.ee ** 2 + trimAntDato.ee ** 2) : null,
    seAnual: anioAntDato ? Math.sqrt(ultimo.ee ** 2 + anioAntDato.ee ** 2) : null,
    baseTrim: trimAntDato ? trimAntDato.valor : null,
    baseAnual: anioAntDato ? anioAntDato.valor : null
  };
}

// A change counts as distinguishable from noise only if it clears 1.96
// combined standard errors -- the same 95% threshold as the confidence
// bands on every chart elsewhere on this site. Without this filter,
// "biggest mover" would almost always just mean "smallest sample": small
// states/categories have the largest standard errors, so their point
// estimates swing the most from quarter to quarter for no real reason.
esSignificativo = (delta, se) =&gt; delta != null && se != null && Math.abs(delta) &gt; 1.96 * se

// Unlike the rest of this series (which leaves color neutral on purpose,
// without implying good/bad), this page does color the direction of
// change -- because it's a scan-many-rows-at-once summary, not a
// case-by-case reading of one indicator. Only the arrow carries color,
// and it's kept pale: coloring the whole value read as too loud and too
// normative (good/bad), which this page shouldn't imply.
// base is the prior period's own value (the denominator this change is
// measured against) -- pass it to also show the relative percent change
// alongside the percentage-point change, e.g. "▲ 0.41 pp (0.7%)".
// The pp figure stays unsigned (direction carried by the arrow alone, the
// site's usual convention), but the percent figure keeps its sign -- it's
// also the sort key for these columns, and an unsigned percent next to a
// down arrow read as if sorting ignored direction, which it doesn't.
formatoDelta = (delta, base) =&gt; {
  if (delta == null) return html`&lt;span&gt;n/a&lt;/span&gt;`;
  if (Math.abs(delta) &lt; 0.005) return html`&lt;span class="delta-flat"&gt;no change&lt;/span&gt;`;
  const subida = delta &gt; 0;
  const clase = subida ? "delta-arrow-up" : "delta-arrow-down";
  const signo = subida ? "▲" : "▼";
  const relativo = (base != null && base !== 0)
    ? html` &lt;span class="data-table-period"&gt;(${(delta / base * 100).toFixed(1)}%)&lt;/span&gt;`
    : "";
  return html`&lt;span&gt;&lt;span class="${clase}"&gt;${signo}&lt;/span&gt; ${Math.abs(delta).toFixed(2)} pp${relativo}&lt;/span&gt;`;
}

cambiosTrimestre = Object.keys(nombres).map(codigo =&gt; {
  const serie = serieDe(codigo);
  if (serie.length === 0) return null;
  const ultimo = serie[serie.length - 1];
  const { deltaTrim, deltaAnual, baseTrim, baseAnual } = calcularDeltas(serie);
  return {
    codigo, nombre: nombres[codigo], valor: ultimo.valor,
    periodo: `${ultimo.anio}-Q${ultimo.trimestre}`,
    deltaTrim, deltaAnual, baseTrim, baseAnual
  };
}).filter(d =&gt; d !== null)

categoriasDeCorte = corte =&gt; [...new Set(datosCortes.filter(d =&gt; d.corte === corte).map(d =&gt; d.categoria_origen))]

// One row per category within a cut, latest value plus QoQ/YoY change --
// same calculation as cambiosTrimestre above, just applied per category
// instead of at the national level. Unsorted here -- ordenarFilas below
// applies whichever order the reader picks at render time.
cambiosPorCorte = (indicador, corte) =&gt; categoriasDeCorte(corte).map(cat =&gt; {
  const serie = datosCortes
    .filter(d =&gt; d.indicador === indicador && d.corte === corte && d.categoria_origen === cat)
    .sort((a, b) =&gt; a.fecha - b.fecha);
  if (serie.length === 0) return null;
  const ultimo = serie[serie.length - 1];
  const { deltaTrim, deltaAnual, baseTrim, baseAnual } = calcularDeltasConSE(serie);
  return {
    categoria: etiquetaEn[cat] ?? cat, valor: ultimo.valor,
    periodo: `${ultimo.anio}-Q${ultimo.trimestre}`,
    deltaTrim, deltaAnual, baseTrim, baseAnual
  };
}).filter(d =&gt; d !== null)

// Sort state for both tables' clickable column headers -- each table gets
// its own independent column/direction pair, so sorting one doesn't
// resort the other. Clicking a header sorts by that column, a fresh
// column starts descending, and a second click on the active column
// toggles descending/ascending. The change columns sort by the relative
// PERCENT change (delta divided by the prior period's own value), not the
// raw percentage-point delta -- pp isn't comparable across rows with very
// different bases (a 0.1 pp move means something different for a 60% rate
// than a 2% one), so sorting on it would rank rows in an order that
// doesn't match what the parenthetical percent figure actually says.
mutable columnaOrdenTrim = "deltaTrim"
mutable direccionOrdenTrim = "desc"
mutable columnaOrdenCorte = "deltaTrim"
mutable direccionOrdenCorte = "desc"

alternarOrdenTrim = columna =&gt; {
  if (columnaOrdenTrim === columna) {
    mutable direccionOrdenTrim = direccionOrdenTrim === "desc" ? "asc" : "desc";
  } else {
    mutable columnaOrdenTrim = columna;
    mutable direccionOrdenTrim = "desc";
  }
}

alternarOrdenCorte = columna =&gt; {
  if (columnaOrdenCorte === columna) {
    mutable direccionOrdenCorte = direccionOrdenCorte === "desc" ? "asc" : "desc";
  } else {
    mutable columnaOrdenCorte = columna;
    mutable direccionOrdenCorte = "desc";
  }
}

// Every header shows a faint double arrow when sortable but inactive, and
// a bold single arrow matching the current direction when it's the active
// sort column -- so the affordance is visible before a reader clicks
// anything, not just after.
flechaOrden = (columnaActiva, columna, direccion) =&gt; columnaActiva === columna
  ? html` &lt;span class="data-table-sort-arrow"&gt;${direccion === "desc" ? "▼" : "▲"}&lt;/span&gt;`
  : html` &lt;span class="data-table-sort-arrow data-table-sort-arrow-inactive"&gt;⇅&lt;/span&gt;`

// Setting onclick as an attribute inside the html`` template (rather than
// as a DOM property on the returned node) doesn't wire up as an event
// listener in Quarto's ojs runtime -- it just stringifies the function into
// the cell's text. Building the &lt;th&gt; node and assigning .onclick directly
// is what actually works. subtitulo (e.g. "(t vs t-1)") renders on its own
// line below the label when given.
celdaEncabezado = (etiqueta, subtitulo, columna, columnaActiva, direccion, alClick) =&gt; {
  const flecha = flechaOrden(columnaActiva, columna, direccion);
  const celda = subtitulo
    ? html`&lt;th class="data-table-sortable"&gt;${etiqueta}${flecha}&lt;br&gt;&lt;span class="data-table-header-sub"&gt;${subtitulo}&lt;/span&gt;&lt;/th&gt;`
    : html`&lt;th class="data-table-sortable"&gt;${etiqueta}${flecha}&lt;/th&gt;`;
  celda.onclick = () =&gt; alClick(columna);
  return celda;
}

// The relative percent change this sorts by: null when there's no prior
// value to compare against (new category, or a value of exactly zero,
// where "percent change" is undefined) -- pushed to the bottom regardless
// of sort direction via the sentinel below, same as a missing pp delta
// would be.
cambioPct = (delta, base) =&gt; (delta != null && base != null && base !== 0) ? delta / base * 100 : null

ordenarFilas = (filas, columnaActiva, direccion) =&gt; {
  const copia = [...filas];
  const signo = direccion === "desc" ? -1 : 1;
  const centinela = direccion === "desc" ? -Infinity : Infinity;
  if (columnaActiva === "valor") return copia.sort((a, b) =&gt; signo * (a.valor - b.valor));
  if (columnaActiva === "deltaAnual") return copia.sort((a, b) =&gt; signo * ((cambioPct(a.deltaAnual, a.baseAnual) ?? centinela) - (cambioPct(b.deltaAnual, b.baseAnual) ?? centinela)));
  return copia.sort((a, b) =&gt; signo * ((cambioPct(a.deltaTrim, a.baseTrim) ?? centinela) - (cambioPct(b.deltaTrim, b.baseTrim) ?? centinela)));
}

// Every (indicator, cut, category) combination's change, filtered to only
// the ones that clear the significance bar -- the pool "biggest mover"
// picks from below. Significance is still evaluated on the raw pp delta
// against its standard error (that's the level estimate the SE actually
// describes), but ranked by relative PERCENT change, same as the table
// below it -- ranking by raw pp here would pick, say, a 6.9 pp move on a
// 27% base over a 4.4 pp move on a 14% base, even though the second is
// the larger swing in relative terms, and disagree with how the table
// right below this headline sorts the exact same category-level data.
todosLosCambios = (campoDelta, campoSE, campoBase) =&gt; {
  const filas = [];
  for (const indicador of indicadoresConCortes) {
    for (const corte of Object.keys(cortes)) {
      for (const cat of categoriasDeCorte(corte)) {
        const serie = datosCortes
          .filter(d =&gt; d.indicador === indicador && d.corte === corte && d.categoria_origen === cat)
          .sort((a, b) =&gt; a.fecha - b.fecha);
        if (serie.length === 0) continue;
        const ultimo = serie[serie.length - 1];
        const deltas = calcularDeltasConSE(serie);
        const delta = deltas[campoDelta], se = deltas[campoSE], base = deltas[campoBase];
        if (esSignificativo(delta, se)) {
          filas.push({
            indicador, corte, categoria: etiquetaEn[cat] ?? cat,
            valor: ultimo.valor, delta, base, periodo: `${ultimo.anio}-Q${ultimo.trimestre}`
          });
        }
      }
    }
  }
  return filas.sort((a, b) =&gt; Math.abs(cambioPct(b.delta, b.base) ?? 0) - Math.abs(cambioPct(a.delta, a.base) ?? 0));
}

// Split into a biggest increase and a biggest decrease per period, rather
// than one overall winner -- todosLosCambios is already sorted by
// |percent change| descending, so the first row matching each sign is
// that direction's biggest mover.
cambiosTrimOrdenados = todosLosCambios("deltaTrim", "seTrim", "baseTrim")
cambiosAnualOrdenados = todosLosCambios("deltaAnual", "seAnual", "baseAnual")
mayorMovimientoTrimSubida = cambiosTrimOrdenados.find(f =&gt; f.delta &gt; 0) ?? null
mayorMovimientoTrimBajada = cambiosTrimOrdenados.find(f =&gt; f.delta &lt; 0) ?? null
mayorMovimientoAnualSubida = cambiosAnualOrdenados.find(f =&gt; f.delta &gt; 0) ?? null
mayorMovimientoAnualBajada = cambiosAnualOrdenados.find(f =&gt; f.delta &lt; 0) ?? null

filaMovimiento = (etiqueta, fila) =&gt; fila
  ? html`&lt;tr&gt;
  &lt;td&gt;${etiqueta}&lt;/td&gt;
  &lt;td&gt;${nombres[fila.indicador]}&lt;span class="data-table-period"&gt; — ${fila.categoria} (${cortes[fila.corte]})&lt;/span&gt;&lt;/td&gt;
  &lt;td class="data-table-num"&gt;${formatoDelta(fila.delta, fila.base)}&lt;/td&gt;
  &lt;td class="data-table-num"&gt;${fila.valor}%&lt;span class="data-table-period"&gt;(${fila.periodo})&lt;/span&gt;&lt;/td&gt;
&lt;/tr&gt;`
  : html`&lt;tr&gt;
  &lt;td&gt;${etiqueta}&lt;/td&gt;
  &lt;td colspan="3" class="data-table-note"&gt;No move clears the 95% confidence threshold this period.&lt;/td&gt;
&lt;/tr&gt;`

ultimoPeriodoValidacion = validaciones.length
  ? `${validaciones[validaciones.length - 1].anio}-Q${validaciones[validaciones.length - 1].trimestre}`
  : ""

// Display order follows the site's own themes, in navbar order: participation,
// informality, unemployment. The CSV arrives sorted by indicator code, which
// interleaved the three. This is a presentation choice, so it lives here and
// not in the CSV.
//
// TSUB sits next to SUBUTIL because underemployment is one of the components
// SUBUTIL aggregates. TCCO goes last: it belongs to none of the three themes
// and has no page of its own.
//
// Anything not listed is appended rather than dropped. A new indicator in the
// upstream pipeline must not disappear from this table -- a silently missing
// row reads as full coverage, which is the same failure the "not validated"
// rows exist to prevent.
ordenTemas = ["TPEA",
              "TIL1", "TIL2", "TOSI1", "TOSI2",
              "TD", "TDAMPL", "SUBUTIL", "TSUB",
              "TCCO"]

ultimasValidaciones = {
  const ultimoAnio = validaciones[validaciones.length - 1]?.anio;
  const ultimoTrim = validaciones[validaciones.length - 1]?.trimestre;
  const rango = v =&gt; {
    const i = ordenTemas.indexOf(v.indicador);
    return i === -1 ? ordenTemas.length : i;
  };
  return validaciones
    .filter(v =&gt; v.anio === ultimoAnio && v.trimestre === ultimoTrim)
    .sort((a, b) =&gt; rango(a) - rango(b) || a.indicador.localeCompare(b.indicador));
}

































































































































































































































































































