indicadores = FileAttachment("data/labor-indicators.csv").csv({ typed: true })

etiquetaSerie = ({ TIL1: "Informality", TOSI1: "Informal sector" })

// The regimen column stores INEGI's own internal codes. The note under the
// chart promises the tooltip names the framework, so it gets a readable name
// rather than the code: "tradicional" is the regular ENOE, "enoen" the Nueva
// Edicion that ran while fieldwork recovered from the 2020 interruption, and
// "enoe_2023" the return to the standard ENOE on the 2023 framework.
etiquetaMarco = ({
  tradicional: "ENOE",
  enoen: "ENOEN",
  enoe_2023: "ENOE, 2023 framework"
})

serieDe = codigo =&gt; indicadores
  .filter(d =&gt; d.indicador === codigo)
  .map(d =&gt; ({
    serie: etiquetaSerie[codigo],
    fecha: new Date(d.anio, (d.trimestre - 1) * 3, 1),
    valor: d.valor,
    anio: d.anio,
    trimestre: d.trimestre,
    regimen: d.regimen
  }))
  .sort((a, b) =&gt; a.fecha - b.fecha)

// 2020-Q2 is genuinely absent (the ETOE gap). Without an explicit
// undefined point Plot bridges it with a straight diagonal, which reads a
// change of method as a gradual transition.
conHuecos = serie =&gt; {
  const resultado = [];
  for (let i = 0; i &lt; serie.length; i++) {
    resultado.push(serie[i]);
    if (i &lt; serie.length - 1) {
      const actual = serie[i], siguiente = serie[i + 1];
      const meses = (siguiente.fecha.getFullYear() - actual.fecha.getFullYear()) * 12
        + (siguiente.fecha.getMonth() - actual.fecha.getMonth());
      if (meses &gt; 3) {
        resultado.push({
          ...actual,
          fecha: new Date(actual.fecha.getFullYear(), actual.fecha.getMonth() + 3, 1),
          valor: undefined
        });
      }
    }
  }
  return resultado;
}

seriesPaso = [serieDe("TIL1"), serieDe("TOSI1")]
puntosPaso = seriesPaso.flat()
lineasPaso = seriesPaso.flatMap(conHuecos)
finalesPaso = seriesPaso.map(s =&gt; s[s.length - 1])
dominioPaso = [etiquetaSerie.TIL1, etiquetaSerie.TOSI1]

// The axis was fixed at [0, 65] while the two series live between 27 and 60,
// so about half the frame was empty and both lines were squeezed into the top
// half. Fit it to the data instead, the same idea as dominioAjustadoSerie on
// the Labor Market MX pages, but with a tighter margin: that helper pads 15%
// of the range, which over a span this wide would leave several points of
// empty axis back. Computed rather than hardcoded so it still fits when the
// quarterly data moves.
dominioPasoY = {
  const valores = puntosPaso.map(d =&gt; d.valor);
  const min = Math.min(...valores), max = Math.max(...valores);
  const margen = (max - min) * 0.06;
  return [min - margen, max + margen];
}

textosPaso = [
  "Straight out of a spreadsheet. A border, gridlines, a marker on every quarter, a legend set apart from the lines, and the software's default colors.",
  "Chart border removed.",
  "Gridlines removed.",
  "Data markers removed.",
  "Axis labels cleaned up and sent to the background.",
  "Series labeled directly, legend dropped.",
  "Each label in its series' color. The chart is now in the style the data pages of this site use: their palette, their type, and one faint grid."
]

lineaPaso = (paso) =&gt; html`&lt;p&gt;${textosPaso[paso]}&lt;/p&gt;`

graficaPasos = (paso) =&gt; {
  const sucio = paso &lt;= 3;
  const casa = paso &gt;= 6;
  const trazo = casa ? "var(--rule)" : "var(--ink-soft)";
  const marcas = [];

  if (paso &lt;= 1) {
    marcas.push(Plot.gridY({ stroke: "var(--ink-soft)", strokeOpacity: 0.85, strokeWidth: 1 }));
  } else if (casa) {
    marcas.push(Plot.gridY({ stroke: "var(--rule)" }));
  }

  if (paso === 0) marcas.push(Plot.frame({ stroke: "var(--ink-soft)" }));

  marcas.push(Plot.lineY(lineasPaso, {
    x: "fecha", y: "valor", z: "serie", stroke: "serie",
    strokeWidth: casa ? 2 : 1.5,
    strokeLinejoin: "round", strokeLinecap: "round"
  }));

  if (paso &lt;= 2) {
    marcas.push(Plot.dot(puntosPaso, {
      x: "fecha", y: "valor", z: "serie", fill: "serie", r: 2.8
    }));
  }

  if (paso &gt;= 5) {
    marcas.push(Plot.text(finalesPaso, {
      x: "fecha", y: "valor", text: "serie",
      textAnchor: "start", dx: 10, fontSize: 13, fontWeight: 500,
      fill: casa ? "serie" : "var(--ink)"
    }));
  }

  if (casa) {
    marcas.push(Plot.dot(finalesPaso, {
      x: "fecha", y: "valor", z: "serie", fill: "serie",
      r: 3.5, stroke: "var(--plot-background)", strokeWidth: 1.5
    }));
    // The tip's data is the union of every series the chart draws, and its
    // title names the series it is describing (CLAUDE.md section 13).
    marcas.push(Plot.tip(puntosPaso, Plot.pointerX({
      x: "fecha", y: "valor",
      title: d =&gt; `${d.serie}\n${d.anio}-Q${d.trimestre} (${etiquetaMarco[d.regimen] ?? d.regimen})\n${d.valor}%`
    })));
  }

  marcas.push(Plot.axisX({
    stroke: trazo,
    tickSize: sucio ? 5 : 0,
    ticks: sucio ? 21 : 5,
    tickRotate: sucio ? -45 : 0,
    fontSize: sucio ? 10 : 12
  }));
  marcas.push(Plot.axisY({
