  return Plot.plot({
    width: 680,
    height: 340,
    marginTop: 30,
    marginLeft: sucio ? 58 : 44,
    marginBottom: sucio ? 58 : 30,
    marginRight: paso &gt;= 5 ? 132 : 24,
